package com.bawaveinfo;

public enum BaRole
{
    ATTACKER,
    DEFENDER,
    COLLECTOR,
    HEALER
}

package com.bawaveinfo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bawaveinfo")
public interface BaWaveInfoConfig extends Config
{
	@ConfigItem(
			keyName = "showOverlay",
			name = "Show Overlay",
			description = "Toggle BA wave info overlay"
	)
	default boolean showOverlay() {
		return true;
	}

	@ConfigItem(
			keyName = "trackSpawns",
			name = "Track NPC Spawns",
			description = "Shows remaining NPCs by decreasing counts as they spawn in each wave"
	)
	default boolean trackSpawns()
	{
		return true;
	}
}

package com.bawaveinfo;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.OverlayPosition;
import java.awt.Color;

public class BaWaveInfoOverlay extends Overlay {
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    private BaWaveInfoPlugin plugin;

    @Inject
    public BaWaveInfoOverlay() {
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setBackgroundColor(new Color(0x88212121, true));
        panelComponent.setPreferredSize(new Dimension(100, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics) {

        if (!plugin.isInBaSession())
        {
            return null;
        }

        panelComponent.getChildren().clear();

        BaRole role = plugin.getCurrentRole();
        WaveInfo info = plugin.getWaveInfo();
        int wave = plugin.getCurrentWave();

        // Not in BA
        if (wave <= 0 || info == null)
        {
            panelComponent.getChildren().add(
                    TitleComponent.builder()
                            .text("Barbarian Assault")
                            .build()
            );

            return panelComponent.render(graphics);
        }

        // In BA
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Wave: " + wave)
                .build());

        if (role == null)
        {
            return panelComponent.render(graphics);
        }

        switch (role) {
            case ATTACKER:
                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left("Fighters")
                                .right(info.fighters() + " / " + info.fighterReserves())
                                .build()
                );

                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left("Rangers")
                                .right(info.rangers() + " / " + info.rangerReserves())
                                .build()
                );

                if (plugin.isTrackingSpawns()) {
                    panelComponent.getChildren().add(
                            LineComponent.builder()
                                    .left("Fighters Left")
                                    .right(String.valueOf(plugin.getFightersRemaining()))
                                    .build()
                    );

                    panelComponent.getChildren().add(
                            LineComponent.builder()
                                    .left("Rangers Left")
                                    .right(String.valueOf(plugin.getRangersRemaining()))
                                    .build()
                    );
                }
                break;

            case DEFENDER:
                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left("Runners")
                                .right(info.runners() + " / " + info.runnerReserves())
                                .build()
                );

                if (plugin.isTrackingSpawns()) {
                    panelComponent.getChildren().add(
                            LineComponent.builder()
                                    .left("Runners Left")
                                    .right(String.valueOf(plugin.getRunnersRemaining()))
                                    .build()
                    );
                }
                break;

            case HEALER:
                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left("Healers")
                                .right(info.healers() + " / " + info.healerReserves())
                                .build()
                );

                if (plugin.isTrackingSpawns()) {
                    panelComponent.getChildren().add(
                            LineComponent.builder()
                                    .left("Healers Left")
                                    .right(String.valueOf(plugin.getHealersRemaining()))
                                    .build()
                    );
                }
                break;

            case COLLECTOR:
                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left("Collector")
                                .build()
                );
                break;
        }
        return panelComponent.render(graphics);
    }
}

package com.bawaveinfo;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import net.runelite.api.events.NpcSpawned;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
	name = "BA Wave Info"
)
public class BaWaveInfoPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private BaWaveInfoConfig config;

	@Inject
	private OverlayManager overlayManager;
	@Inject
	private BaWaveInfoOverlay overlay;
	private int currentWave = -1;
	private BaRole currentRole;
	private int runnersRemaining;
	private int healersRemaining;
	private int fightersRemaining;
	private int rangersRemaining;
	private boolean inBaSession;
	private static final Pattern BA_WAVE_PATTERN = Pattern.compile("Wave:\\s*(\\d+)");
	private static final String BA_END_ROUND = "The Queen has arrived and you can no longer use the horn of glory!";
	@Override
	protected void startUp() throws Exception
	{
		log.debug("BA Wave Info started!");
		if (config.showOverlay())
		{
			overlayManager.add(overlay);
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.debug("BA Wave Info stopped!");
		overlayManager.remove(overlay);
		currentWave = -1;
	}


	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("bawaveinfo"))
		{
			return;
		}

		if (event.getKey().equals("showOverlay")) {
			if (config.showOverlay())
			{
				overlayManager.add(overlay);
			} else {
				overlayManager.remove(overlay);
			}
		}
	}

	public BaRole getCurrentRole()
	{
		return currentRole;
	}

	public int getCurrentWave()
	{
		return currentWave;
	}

	public WaveInfo getWaveInfo()
	{
		if (currentWave <= 0)
		{
			return null;
		}
		return WaveData.get(getCurrentWave());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();

		// end of BA round
		if (message.contains(BA_END_ROUND))
		{
			handleBaCompletion(message);
		}

		// handle wave updates for overlay
		if (message.contains("Wave"))
		{
			extractWave(message);
			return;
		}

	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Widget root = client.getWidget(256, 0);

		if (root == null)
		{
			return;
		}

		updateRole();
	}

	// Maybe make this a bit more nuanced later, it will do for now
	// Logic for showing number of remaining spawns
	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (!config.trackSpawns() || currentWave <= 0)
		{
			return;
		}

		NPC npc = event.getNpc();
		int npcId = npc.getId();

		if (NpcData.HEALER_NPCS.contains(npcId))
		{
			if (healersRemaining > 0)
			{
				healersRemaining--;
			}
		}
		else if (NpcData.RUNNER_NPCS.contains(npcId))
		{
			if (runnersRemaining > 0)
			{
				runnersRemaining--;
			}
		}
		else if (NpcData.FIGHTER_NPCS.contains(npcId))
		{
			if (fightersRemaining > 0)
			{
				fightersRemaining--;
			}
		}
		else if (NpcData.RANGER_NPCS.contains(npcId))
		{
			if (rangersRemaining > 0)
			{
				rangersRemaining--;
			}
		}
	}

	private void extractWave(String message)
	{

		if (!message.startsWith("---- Wave:"))
		{
			return;
		}

		Matcher waveMatcher = BA_WAVE_PATTERN.matcher(message);

		if (waveMatcher.find())
		{
			currentWave = Integer.parseInt(waveMatcher.group(1));
			startWaveState();
			log.info("Detected BA wave: {}", currentWave);
		}
	}

	private void updateRole()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		String playerName = client.getLocalPlayer().getName();

		for (int i = 8; i <= 12; i++)
		{
			Widget playerWidget = client.getWidget(256, i);

			if (playerWidget == null)
			{
				continue;
			}

			if (!playerName.equals(playerWidget.getText()))
			{
				continue;
			}

			Widget roleWidget = client.getWidget(256, i + 10);

			if (roleWidget == null)
			{
				return;
			}

			BaRole newRole = getRoleFromModelId(roleWidget.getModelId());

			if (newRole != currentRole)
			{
				currentRole = newRole;
				log.info("Resolved role: {}", currentRole);
			}

			return;
		}
	}

	private BaRole getRoleFromModelId(int modelId)
	{
		switch (modelId)
		{
			case 20561:
				return BaRole.ATTACKER;

			case 20566:
				return BaRole.DEFENDER;

			case 20563:
				return BaRole.COLLECTOR;

			case 20569:
				return BaRole.HEALER;

			default:
				return null;
		}
	}

	private void startWaveState()
	{
		WaveInfo waveData = WaveData.get(currentWave);

		if (waveData == null)
		{
			return;
		}

		inBaSession = true;

		runnersRemaining = waveData.runners() + waveData.runnerReserves();
		rangersRemaining = waveData.rangers()+ waveData.rangerReserves();
		fightersRemaining = waveData.fighters() + waveData.fighterReserves();
		healersRemaining = waveData.healers() + waveData.healerReserves();
	}

	private void handleBaCompletion(String message)
	{
			log.info("Wave 10 completed, resetting state");
			currentWave = -1;
			currentRole = null;
			inBaSession = false;

			runnersRemaining = 0;
			healersRemaining = 0;
			rangersRemaining = 0;
			fightersRemaining = 0;
	}

	public int getFightersRemaining()
	{
		return fightersRemaining;
	}

	public int getRunnersRemaining()
	{
		return runnersRemaining;
	}

	public int getHealersRemaining()
	{
		return healersRemaining;
	}

	public int getRangersRemaining()
	{
		return rangersRemaining;
	}

	public boolean isTrackingSpawns()
	{
		return config.trackSpawns();
	}

	public boolean isInBaSession()
	{
		return inBaSession;
	}

	@Provides
	BaWaveInfoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BaWaveInfoConfig.class);
	}
}

package com.bawaveinfo;

import java.util.Set;

