    public static final Set<Integer> RUNNER_NPCS = Set.of(1669,5748, 5749, 5750, 5751, 5752, 5753, 5754, 5755, 5756);
    public static final Set<Integer> FIGHTER_NPCS = Set.of(1668,5757, 5740, 5741, 5742, 5743, 5744, 5745, 5746, 5747);
    public static final Set<Integer> RANGER_NPCS = Set.of(1667,5739, 5758, 5759, 5760, 5761, 5762, 5763, 5764, 5765);
}

package com.bawaveinfo;


import java.util.Map;

public class WaveData {
    private static final Map<Integer, WaveInfo> WAVES = Map.of(
            1, new WaveInfo(2, 2, 2, 2, 0, 2,2,0),
            2, new WaveInfo(2, 2, 3, 2, 1, 3,1,1),
            3, new WaveInfo(2, 5, 3, 2, 1, 0,3,2),
            4, new WaveInfo(3, 5, 3, 3, 1, 1,3,1),
            5, new WaveInfo(4, 3, 3, 4, 1, 3,1,1),
            6, new WaveInfo(4, 5, 5, 4, 2, 1,2,2),
            7, new WaveInfo(5, 5, 6, 4, 3, 2,1,1),
            8, new WaveInfo(5, 7, 5, 5, 2, 0,3,2),
            9, new WaveInfo(5, 6, 7, 6, 2, 2,1,4),
            10, new WaveInfo(5, 5, 6, 4, 3, 2,1,1)
    );

    public static WaveInfo get(int wave)
    {
        return WAVES.get(wave);
    }
}

package com.bawaveinfo;

public class WaveInfo
{
    private final int runners;
    private final int fighters;
    private final int rangers;
    private final int healers;

    private final int healerReserves;
    private final int fighterReserves;
    private final int rangerReserves;
    private final int runnerReserves;

    public WaveInfo(
            int runners,
            int fighters,
            int rangers,
            int healers,
            int healerReserves,
            int fighterReserves,
            int rangerReserves,
            int runnerReserves
    )
    {
        this.runners = runners;
        this.fighters = fighters;
        this.rangers = rangers;
        this.healers = healers;

        this.healerReserves = healerReserves;
        this.fighterReserves = fighterReserves;
        this.rangerReserves = rangerReserves;
        this.runnerReserves = runnerReserves;
    }

    public int runners() { return runners; }
    public int fighters() { return fighters; }
    public int rangers() { return rangers; }
    public int healers() { return healers; }

    public int healerReserves() { return healerReserves; }
    public int fighterReserves() { return fighterReserves; }
    public int rangerReserves() { return rangerReserves; }
    public int runnerReserves() { return runnerReserves; }
}

